#include <iostream>
#include <cstdio>
#include <cstring>
#include <vector>
#include <queue>
using namespace std;

constexpr int INF = 1 << 29;
constexpr int MAX_N = 500;

struct Arc {
    int from, to, capacity, flow;
};

bool passable[11][11];
vector<int> graph[MAX_N];
vector<Arc> network;
int level[MAX_N], current[MAX_N], grid_size, exit_row, exit_col, time_budget, distances[11][11], capacities[11][11];

int compute_path_length(int src_r, int src_c, int dst_r, int dst_c) {
    queue<pair<int, pair<int, int>>> q;
    q.emplace(0, make_pair(src_r, src_c));
    int dist_map[11][11];
    for (int i = 0; i < grid_size; ++i)
        for (int j = 0; j < grid_size; ++j)
            dist_map[i][j] = INF;
    while (!q.empty()) {
        int dist = q.front().first;
        int r = q.front().second.first;
        int c = q.front().second.second;
        q.pop();
        dist_map[r][c] = dist;
        if (r > 0 && passable[r-1][c]) {
            int nr = r - 1, nc = c;
            if (dist_map[nr][nc] > dist + 1) {
                bool ok1 = (nr == dst_r && nc == dst_c && distances[nr][nc] >= dist + 1);
                bool ok2 = (!(nr == dst_r && nc == dst_c) && distances[nr][nc] > dist + 1);
                if (ok1 || ok2) q.emplace(dist + 1, make_pair(nr, nc));
            }
        }
        if (c > 0 && passable[r][c-1]) {
            int nr = r, nc = c - 1;
            if (dist_map[nr][nc] > dist + 1) {
                bool ok1 = (nr == dst_r && nc == dst_c && distances[nr][nc] >= dist + 1);
                bool ok2 = (!(nr == dst_r && nc == dst_c) && distances[nr][nc] > dist + 1);
                if (ok1 || ok2) q.emplace(dist + 1, make_pair(nr, nc));
            }
        }
        if (r < grid_size-1 && passable[r+1][c]) {
            int nr = r + 1, nc = c;
            if (dist_map[nr][nc] > dist + 1) {
                bool ok1 = (nr == dst_r && nc == dst_c && distances[nr][nc] >= dist + 1);
                bool ok2 = (!(nr == dst_r && nc == dst_c) && distances[nr][nc] > dist + 1);
                if (ok1 || ok2) q.emplace(dist + 1, make_pair(nr, nc));
            }
        }
        if (c < grid_size-1 && passable[r][c+1]) {
            int nr = r, nc = c + 1;
            if (dist_map[nr][nc] > dist + 1) {
                bool ok1 = (nr == dst_r && nc == dst_c && distances[nr][nc] >= dist + 1);
                bool ok2 = (!(nr == dst_r && nc == dst_c) && distances[nr][nc] > dist + 1);
                if (ok1 || ok2) q.emplace(dist + 1, make_pair(nr, nc));
            }
        }
    }
    return dist_map[dst_r][dst_c];
}

void link(int u, int v, int cap) {
    network.push_back({u, v, cap, 0});
    network.push_back({v, u, 0, 0});
    graph[u].push_back((int)network.size() - 2);
    graph[v].push_back((int)network.size() - 1);
}

bool construct_levels() {
    fill(level, level + grid_size * grid_size * 2 + 2, -1);
    queue<int> q;
    q.push(0);
    level[0] = 0;
    while (!q.empty() && level[grid_size * grid_size * 2 + 1] == -1) {
        int u = q.front(); q.pop();
        for (int idx : graph[u]) {
            int v = network[idx].to;
            if (level[v] == -1 && network[idx].flow < network[idx].capacity) {
                level[v] = level[u] + 1;
                q.push(v);
            }
        }
    }
    return level[grid_size * grid_size * 2 + 1] != -1;
}

int send_flow(int u, int limit) {
    if (limit == 0) return 0;
    if (u == grid_size * grid_size * 2 + 1) return limit;
    for (; current[u] < (int)graph[u].size(); ++current[u]) {
        int idx = graph[u][current[u]];
        int v = network[idx].to;
        if (level[v] != level[u] + 1) continue;
        int augment = send_flow(v, min(limit, network[idx].capacity - network[idx].flow));
        if (augment) {
            network[idx].flow += augment;
            network[idx ^ 1].flow -= augment;
            return augment;
        }
    }
    return 0;
}

int compute_maxflow() {
    int flow = 0;
    while (construct_levels()) {
        fill(current, current + grid_size * grid_size * 2 + 2, 0);
        int delta;
        while ((delta = send_flow(0, INF))) flow += delta;
    }
    return flow;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    cin >> grid_size >> time_budget;
    queue<pair<int, pair<int, int>>> q;
    char ch;
    int node = 1;
    for (int i = 0; i < grid_size; ++i) {
        for (int j = 0; j < grid_size; ++j) {
            cin >> ch;
            distances[i][j] = time_budget;
            if (ch == 'Z') {
                exit_row = i;
                exit_col = j;
                passable[i][j] = false;
            } else if (ch == 'Y') {
                passable[i][j] = false;
            } else {
                passable[i][j] = true;
            }
            link(0, node++, (ch == 'Z' || ch == 'Y') ? 0 : ch - '0');
        }
    }
    node = grid_size * grid_size + 1;
    for (int i = 0; i < grid_size; ++i) {
        for (int j = 0; j < grid_size; ++j) {
            cin >> ch;
            if (ch >= '0' && ch <= '9') capacities[i][j] = ch - '0';
            link(node++, grid_size * grid_size * 2 + 1, (ch == 'Z' || ch == 'Y') ? 0 : ch - '0');
        }
    }
    q.emplace(0, make_pair(exit_row, exit_col));
    while (!q.empty()) {
        int d = q.front().first;
        int r = q.front().second.first;
        int c = q.front().second.second;
        q.pop();
        distances[r][c] = d;
        if (r > 0 && d + 1 < distances[r - 1][c] && passable[r - 1][c])
            q.emplace(d + 1, make_pair(r - 1, c));
        if (c > 0 && d + 1 < distances[r][c - 1] && passable[r][c - 1])
            q.emplace(d + 1, make_pair(r, c - 1));
        if (r < grid_size - 1 && d + 1 < distances[r + 1][c] && passable[r + 1][c])
            q.emplace(d + 1, make_pair(r + 1, c));
        if (c < grid_size - 1 && d + 1 < distances[r][c + 1] && passable[r][c + 1])
            q.emplace(d + 1, make_pair(r, c + 1));
    }
    int node_idx = 0;
    for (int r1 = 0; r1 < grid_size; ++r1) {
        for (int c1 = 0; c1 < grid_size; ++c1) {
            int sink_node = grid_size * grid_size;
            ++node_idx;
            for (int r2 = 0; r2 < grid_size; ++r2) {
                for (int c2 = 0; c2 < grid_size; ++c2) {
                    ++sink_node;
                    if (passable[r1][c1] && passable[r2][c2] &&
                        compute_path_length(r1, c1, r2, c2) <= time_budget)
                        link(node_idx, sink_node, INF);
                }
            }
        }
    }
    cout << compute_maxflow() << '\n';
    return 0;
}
